// Eingabe: projekt_id aus dem aufrufenden Workflow (BERICHT 1) oder aus dem Testlauf (Projekt-ID hier eintragen); monat als JJJJ-MM nur bei Projekten über mehrere Monate;
// aufgaben_dl = "ja" nur, wenn ausdrücklich gewünscht: dann zählt je Aufgabe deren eigene Dienstleistung (kostet je Aufgabe einen Papierkram-Abruf)
const t = $('Testlauf (manuell)').isExecuted;
// Testlauf ohne feste Projekt-ID: für einen Test die Papierkram-Projekt-ID hier eintragen (Stefan 17.10.2026)
const ein = t ? { projekt_id: '', monat: '', aufgaben_dl: '' } : $('Start durch Workflow').first().json;
const id = String(ein.projekt_id ?? '').trim();
const monat = String(ein.monat ?? '').trim();
const aufgaben_dl = ['ja', 'true', '1', 'an'].includes(String(ein.aufgaben_dl ?? '').trim().toLowerCase());
if (t && !id) throw new Error('Testlauf: kein Projekt gewählt. Die Papierkram-Projekt-ID im Knoten „Eingabe prüfen“ eintragen.');
if (!/^\d+$/.test(id)) throw new Error('Keine gültige Papierkram-Projekt-ID übergeben.');
return [{ json: { projekt_id: id, monat, aufgaben_dl } }];

// Vollständigkeit prüfen: Jede timeBuzzer-Zeit des Projekts im Berichtszeitraum muss aktuell in Papierkram stehen.
// Sonst wird kein Bericht erstellt, damit Bericht und Rechnung nie auseinanderlaufen.
const P = $('PK – Projekt').first().json;
const DB = $('Sync-Gedächtnis laden').first().json;
const seiten = $('PK – Zeiteinträge').all().map(i => i.json);
const tbSeiten = $('TB – Aktivitäten abrufen').all();
const B = iso => DateTime.fromISO(iso, { setZone: true }).setZone('Europe/Berlin');
const s = v => String(v ?? '').trim();

if (!P || !P.id) throw new Error('Projekt nicht in Papierkram gefunden.');
const letzte = tbSeiten.length ? (tbSeiten[tbSeiten.length - 1].json.activities || []) : null;
if (!letzte || letzte.length >= 100) throw new Error('timeBuzzer-Zeiten unvollständig abgerufen. Bericht wurde nicht erstellt.');

const pkIds = new Set();
for (const sei of seiten) for (const e of (sei.entries || [])) if (!e.record_state || e.record_state === 'active') pkIds.add(String(e.id));

const zuordnung = {};          // timeBuzzer-Aktivität -> Sync-Gedächtnis
const pkStatus = {};           // Papierkram-Eintrag -> Status im Sync-Gedächtnis
for (const z of (DB.zeiten || [])) {
  if (z.s === 'active') zuordnung[String(z.a)] = z;
  pkStatus[String(z.pk)] = z.s;
}
const aufgabeTb = DB.aufgaben_tb || {};
// Startdatum der Zeiterfassung aus ally_einstellungen (zeiterfassung_ab, JJJJ-MM-TT, über "Sync-Gedächtnis laden"); ab hier überträgt SYNC 4 die Zeiten.
// Leer = keine Untergrenze (Stefan 17.10.2026)
const abText = s(DB.zeiterfassung_ab);
const abTag = abText ? DateTime.fromISO(abText, { zone: 'Europe/Berlin' }) : null;
if (abText && (!/^\d{4}-\d{2}-\d{2}$/.test(abText) || !abTag.isValid)) throw new Error('Einstellung zeiterfassung_ab ist ungültig: ' + abText + ' (erwartet JJJJ-MM-TT). Bericht wurde nicht erstellt.');
const STICHTAG = abTag ? abTag.startOf('day').toJSDate() : null;

// Zeitraum wie im Bericht (aus "Zeitraum bestimmen")
const Z = $('Zeitraum bestimmen').first().json;
const von = DateTime.fromISO(Z.von, { zone: 'Europe/Berlin' }).startOf('day');
const bis = DateTime.fromISO(Z.bis, { zone: 'Europe/Berlin' }).endOf('day');

const probleme = [];
const tile = s(DB.projekt_tile);
let geprueft = 0;
if (tile) {
  const gesehen = new Set();
  for (const sei of tbSeiten) for (const a of (sei.json.activities || [])) {
    if (gesehen.has(a.id)) continue;
    gesehen.add(a.id);
    if (!Array.isArray(a.tiles) || String(a.tiles[1]) !== tile) continue;
    if (STICHTAG && new Date(a.startDate) < STICHTAG) continue;
    const st = B(a.startDate);
    if ((von && st < von) || (bis && st > bis)) continue;
    geprueft++;
    const was = st.toFormat('dd.LL.') + ' ' + st.toFormat('HH:mm') + ' Uhr, Aufgabe „' + (aufgabeTb[String(a.tiles[2])] || 'unbekannt') + '“';
    if (!a.endDate) { probleme.push(was + ': Zeiterfassung läuft noch'); continue; }
    const m = zuordnung[String(a.id)];
    if (!m) { // Plan 43: Aufgaben (SYNC 3) und Zeiten (SYNC 4) werden direkt vor dieser Prüfung abgeglichen – der frühere Hinweis, den Sync von Hand zu starten, trifft nicht mehr zu
    probleme.push(was + ': noch nicht in Papierkram (beim Abgleich direkt vor dem Bericht nicht übertragen)'); continue; }
    if (!pkIds.has(String(m.pk))) { probleme.push(was + ': in Papierkram nicht beim Projekt ' + s(P.name) + ' gefunden'); continue; }
    const hash = `${a.startDate}|${a.endDate}|${a.note || ''}|${a.tiles[0]}|${a.tiles[1]}|${a.tiles[2]}`;
    if (m.h !== hash) probleme.push(was + ': Änderung aus timeBuzzer noch nicht in Papierkram');
  }
}
// Einträge, die in timeBuzzer gelöscht wurden, deren Löschung in Papierkram aber fehlschlug
for (const id of pkIds) if (pkStatus[id] === 'loeschen_fehlgeschlagen') probleme.push('Papierkram-Zeiteintrag ' + id + ': in timeBuzzer gelöscht, in Papierkram aber noch vorhanden');

if (probleme.length) {
  const liste = probleme.slice(0, 8).join('; ') + (probleme.length > 8 ? '; und ' + (probleme.length - 8) + ' weitere' : '');
  // Plan 43 (Koordinator 31.10.2026): Ist der Aufgaben-Abgleich (SYNC 3) direkt vorher fehlgeschlagen, steht das mit kurzer Ursache dabei (Knoten „Abgleich prüfen“)
  const AB = $('Abgleich prüfen').isExecuted ? ($('Abgleich prüfen').first().json || {}) : {};
  const abg = AB.abgleich_ok === false ? ' Der Abgleich der Aufgaben timeBuzzer → Papierkram direkt vorher ist fehlgeschlagen' + (AB.ursache ? ': ' + String(AB.ursache).replace(/[.\s…]*$/, '') : '') + '.' : '';
  throw new Error('Bericht nicht erstellt, weil Papierkram nicht vollständig ist: ' + liste + '.' + abg);
}
return [{ json: { ok: true, geprueft, projekt_tile: tile || null } }];

// Monatsbericht bauen – Grundlage sind ausschließlich die Zeiteinträge aus Papierkram.
// Gerechnet wird wie auf der Papierkram-Rechnung: je Eintrag die von Papierkram gerundete Zeit (billable_duration),
// Summe in Stunden je Dienstleistung auf 2 Nachkommastellen gerundet, erst dann mal Stundensatz.
// Stundensatz: Standard-Dienstleistung des Projekts; nur mit Schalter "aufgaben_dl" die Dienstleistung der jeweiligen Aufgabe.
const CD = $('Corporate Design (CD 1)').first().json;
// Name des eigenen Unternehmens aus dem Corporate Design (CD 1, Einstellungen > Unternehmen); ohne Namen kein Firmentext
const FIRMA = String((CD && CD.unternehmen) || '').trim();
const P = $('PK – Projekt').first().json;
const personen = ($('PK – Ansprechpartner').first().json.entries) || [];
const seiten = $('PK – Zeiteinträge').all().map(i => i.json);
const DB = $('Sync-Gedächtnis laden').first().json;
const Z = $('Zeitraum bestimmen').first().json;
// Aufgabennamen: zuerst aus Papierkram (Projekt), ergänzend aus dem Sync-Gedächtnis
const aufgabenNamen = Object.assign({}, DB.aufgaben_pk || {});
const pkAufgaben = (P.tasks && Array.isArray(P.tasks.entries)) ? P.tasks.entries : [];
for (const t of pkAufgaben) aufgabenNamen[String(t.id)] = String(t.name || '');
const ERSTELLER = { name: String(DB.kontakt_name || '').trim(), mail: String(DB.kontakt_mail || '').trim() };
if (!ERSTELLER.name || !ERSTELLER.mail) throw new Error('Kontakt für den Bericht fehlt (ally_einstellungen: absender_name, bericht_kontakt_mail).');

const s = v => String(v ?? '').trim();
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const r2 = x => Math.round((x + Number.EPSILON) * 100) / 100;
const euro = v => Number(v || 0).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const zahl2 = v => Number(v || 0).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const hhmm = min => Math.floor(min / 60) + ':' + String(Math.round(min % 60)).padStart(2, '0');
const B = iso => DateTime.fromISO(iso, { setZone: true }).setZone('Europe/Berlin');

// Vollständigkeit: alle Seiten, keine doppelten, Anzahl muss zur Gesamtzahl von Papierkram passen
const gesamtLaut = Number(seiten[0] && seiten[0].total_entries);
const gesehen = new Set();
const eintraege = [];
for (const sei of seiten) for (const e of (sei.entries || [])) {
  if (gesehen.has(e.id)) continue;
  gesehen.add(e.id);
  eintraege.push(e);
}
if (!Number.isFinite(gesamtLaut) || eintraege.length !== gesamtLaut) throw new Error('Zeiteinträge aus Papierkram unvollständig: ' + eintraege.length + ' von ' + gesamtLaut + ' abgerufen. Bericht wurde nicht erstellt.');
const fremd = eintraege.filter(e => String(e.project_id) !== String(P.id));
if (fremd.length) throw new Error('Papierkram hat Einträge anderer Projekte geliefert. Bericht wurde nicht erstellt.');
const aktiv = eintraege.filter(e => !e.record_state || e.record_state === 'active');
const ohneName = [...new Set(aktiv.map(e => String(e.task_id)).filter(id => !aufgabenNamen[id]))];
if (ohneName.length) throw new Error('Aufgabe(n) ' + ohneName.join(', ') + ' nicht im Sync-Gedächtnis. Bericht wurde nicht erstellt.');

const preis = Number(P.default_proposition && P.default_proposition.price);
if (!Number.isFinite(preis) || preis <= 0) throw new Error('Projekt ' + s(P.name) + ' hat keinen Stundensatz (Dienstleistung) in Papierkram.');
const stdDL = { id: String(P.default_proposition.id || 'projekt'), name: s(P.default_proposition.name) || 'Dienstleistung', preis };
// Dienstleistung je Aufgabe (nur mit Schalter): ohne eigene Dienstleistung gilt die des Projekts
const DLS = $('Dienstleistungen sammeln').first().json || {};
const dlVon = e => {
  if (DLS.an !== true) return stdDL;
  const k = String(e.task_id);
  if (!DLS.aufgaben || !(k in DLS.aufgaben)) throw new Error('Dienstleistung der Aufgabe ' + (aufgabenNamen[k] || k) + ' wurde nicht abgerufen. Bericht wurde nicht erstellt.');
  const d = DLS.aufgaben[k];
  if (!d) return stdDL;
  if (!Number.isFinite(d.preis) || d.preis <= 0 || (d.einheit && d.einheit !== 'hour')) throw new Error('Die Dienstleistung „' + d.name + '“ der Aufgabe ' + (aufgabenNamen[k] || k) + ' hat keinen Stundensatz. Bericht wurde nicht erstellt.');
  return d;
};
// Abrechnung wie die Papierkram-Rechnung: je Dienstleistung Stunden auf 2 Stellen, mal Satz, dann addiert
const abrechnung = liste => {
  const m = new Map();
  for (const e of liste) {
    if (e.unbillable) continue;
    const sek = Number(e.billable_duration || 0);
    if (!sek) continue;
    const d = dlVon(e);
    if (!m.has(d.id)) m.set(d.id, { id: d.id, name: d.name, preis: d.preis, sek: 0 });
    m.get(d.id).sek += sek;
  }
  const posten = [...m.values()].map(p => { const st = r2(p.sek / 3600); return Object.assign(p, { stunden: st, betrag: r2(st * p.preis) }); }).sort((a, b) => a.name.localeCompare(b.name, 'de'));
  return { posten, stunden: r2(posten.reduce((a, p) => a + p.stunden, 0)), betrag: r2(posten.reduce((a, p) => a + p.betrag, 0)) };
};
// Budget: Geldbudget (money) oder Stundenbudget (working_time, in Stunden)
const budgetGeld = P.budget_type === 'money' && s(P.budget_money) !== '' && Number(P.budget_money) > 0 ? Number(P.budget_money) : null;
const budgetMin = P.budget_type === 'working_time' && s(P.budget_time) !== '' && Number(P.budget_time) > 0 && (P.budget_time_unit || 'hour') === 'hour' ? Math.round(Number(P.budget_time) * 60) : null;

// Zeitraum aus "Zeitraum bestimmen": bei Ein-Monats-Projekten zählen alle Einträge des Projekts (wie auf der Rechnung),
// bei Projekten über mehrere Monate nur die Einträge des gewählten Monats
const von = DateTime.fromISO(Z.von, { zone: 'Europe/Berlin' }).startOf('day');
const bis = DateTime.fromISO(Z.bis, { zone: 'Europe/Berlin' }).startOf('day');
const tagVon = e => B(e.started_at).startOf('day');
const imZeitraum = Z.monatsmodus ? aktiv.filter(e => tagVon(e) >= von && tagVon(e) <= bis) : aktiv;
if (!imZeitraum.length) throw new Error('Für ' + s(P.name) + ' gibt es in Papierkram ' + (Z.monatsmodus ? 'im Zeitraum ' + von.toFormat('dd.LL.yyyy') + ' – ' + bis.toFormat('dd.LL.yyyy') + ' ' : '') + 'keine Zeiteinträge.');
const ausserhalb = Z.monatsmodus ? [] : aktiv.filter(e => tagVon(e) < von || tagVon(e) > bis);
// Verbrauch bis Ende des Berichtszeitraums (für das Budget bei Projekten über mehrere Monate)
const bisEnde = Z.monatsmodus ? aktiv.filter(e => tagVon(e) <= bis) : aktiv;

// Zeilen: Einträge mit gleichem Tag, gleicher Aufgabe und gleicher Notiz werden zusammengefasst (Summe der gerundeten Zeiten)
const TAGE = ['', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];
const gruppen = new Map();
let summeSek = 0, summeEchtSek = 0, nichtBerechnetSek = 0;
for (const e of imZeitraum.sort((a, b) => B(a.started_at) - B(b.started_at))) {
  const st = B(e.started_at);
  const abrechnen = e.unbillable ? 0 : Number(e.billable_duration || 0);
  summeSek += abrechnen;
  summeEchtSek += Number(e.duration || 0);
  if (e.unbillable) nichtBerechnetSek += Number(e.duration || 0);
  const notiz = s(e.comments).replace(/\r\n?/g, '\n');
  const key = st.toISODate() + '|' + e.task_id + '|' + notiz + '|' + (e.unbillable ? 'u' : 'b');
  if (!gruppen.has(key)) gruppen.set(key, { tag: st.startOf('day'), aufgabe: aufgabenNamen[String(e.task_id)], notiz, sek: 0, unbillable: !!e.unbillable, preis: e.unbillable ? 0 : dlVon(e).preis, n: 0 });
  const g = gruppen.get(key);
  g.sek += e.unbillable ? Number(e.duration || 0) : abrechnen;
  g.n += 1;
}
const zeilen = [...gruppen.values()];

// Rechnung wie Papierkram
const minuten = Math.round(summeSek / 60);
const R = abrechnung(imZeitraum);
const stunden = R.stunden;
const betrag = R.betrag;
const mehrere = R.posten.length > 1;
const satz = R.posten.length === 1 ? R.posten[0].preis : preis;
// Bisheriger Gesamtverbrauch bis Ende des Zeitraums, gerechnet wie eine Rechnung über diese Einträge
const kumSek = bisEnde.reduce((a, e) => a + (e.unbillable ? 0 : Number(e.billable_duration || 0)), 0);
const kumMinuten = Math.round(kumSek / 60);
const kumBetrag = abrechnung(bisEnde).betrag;
const rest = budgetGeld !== null ? r2(budgetGeld - kumBetrag) : (budgetMin !== null ? budgetMin - kumMinuten : null);
const anteil = budgetGeld !== null ? betrag / budgetGeld * 100 : (budgetMin !== null ? minuten / budgetMin * 100 : null);
const anteilKum = budgetGeld !== null ? kumBetrag / budgetGeld * 100 : (budgetMin !== null ? kumMinuten / budgetMin * 100 : null);
const kumText = budgetGeld !== null ? euro(kumBetrag) : hhmm(kumMinuten) + ' h';
const zeitText = m => (m < 0 ? '-' : '') + hhmm(Math.abs(m)) + ' h';
const budgetText = budgetGeld !== null ? euro(budgetGeld) : (budgetMin !== null ? zeitText(budgetMin) : null);
const restText = budgetGeld !== null ? euro(rest) : (budgetMin !== null ? zeitText(rest) : null);

// Wochen (ISO-KW), Tage auf den Berichtszeitraum begrenzt
const wochen = new Map();
for (const z of zeilen) {
  const k = z.tag.weekYear * 100 + z.tag.weekNumber;
  if (!wochen.has(k)) {
    const mo = z.tag.startOf('week'), so = mo.plus({ days: 6 });
    const a = mo < von ? von : mo, b = so > bis ? bis : so;
    wochen.set(k, { kw: z.tag.weekNumber, a, b, min: 0, wert: 0, zeilen: [] });
  }
  const w = wochen.get(k);
  if (!z.unbillable) { w.min += z.sek / 60; w.wert += z.sek / 3600 * z.preis; }
  w.zeilen.push(z);
}
const wochenListe = [...wochen.entries()].sort((x, y) => x[0] - y[0]).map(x => x[1]);
const spanne = (a, b) => a.hasSame(b, 'day') ? a.toFormat('dd.LL.') : (a.hasSame(b, 'month') ? a.toFormat('dd.') : a.toFormat('dd.LL.')) + '–' + b.toFormat('dd.LL.');

const MONATE = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
const titel = 'Monatsbericht ' + MONATE[von.month - 1] + ' ' + von.year;
const ansprech = personen.find(p => p.default === true) || personen[0];
const ansprechName = ansprech ? s([s(ansprech.first_name), s(ansprech.last_name)].filter(Boolean).join(' ')) : '';
const kunde = s(P.customer && P.customer.name);
const jetzt = DateTime.now().setZone('Europe/Berlin');

const C = { dunkel: CD.farben.dunkel, akzent: CD.farben.akzent, akzentDunkel: CD.farben.akzentDunkel, hell: CD.farben.hell, grau: CD.farben.grau, linie: CD.abgeleitet.tabellenLinie, warn: CD.farben.warnung, weiss: CD.farben.textAufDunkel, nebenDunkel: CD.abgeleitet.dunkelNebentext };
const kachel = (wert, label, cls) => '<div class="kachel"><div class="wert' + (cls ? ' ' + cls : '') + '">' + wert + '</div><div class="label">' + label + '</div></div>';
const seg = (w, cls) => w > 0 ? '<div class="fuell' + cls + '" style="width:' + w.toFixed(1) + '%"></div>' : '';
const vorherP = Z.monatsmodus && anteilKum !== null ? Math.max(0, anteilKum - anteil) : 0;
const balken = anteilKum === null ? '' : '<div class="balken">' + seg(Math.min(100, vorherP), ' alt') + seg(Math.min(100 - Math.min(100, vorherP), anteil), anteilKum > 100 ? ' warn' : '') + '</div><div class="balkentext">' +
  (Z.monatsmodus ? zahl2(r2(anteilKum)) + ' % des Budgets bis ' + bis.toFormat('dd.LL.yyyy') + ' verbraucht, davon ' + zahl2(r2(anteil)) + ' % in diesem Monat' : zahl2(r2(anteil)) + ' % des Budgets verbraucht') + '</div>';

// Wochenanteil: mit Budget als Anteil am Budget (Wochen ergeben zusammen den Gesamtverbrauch), ohne Budget als Anteil an der Gesamtzeit
const mitBudget = anteil !== null;
const gesamtProzent = mitBudget ? r2(anteil) : 100;
// auf zwei Stellen runden und so verteilen, dass die Wochen genau die Gesamtzahl ergeben
// Geldbudget: Anteil nach Betrag der Woche (bei mehreren Stundensätzen gewichtet), sonst nach Zeit
const summeWert = wochenListe.reduce((a, w) => a + w.wert, 0);
const rohP = wochenListe.map(w => budgetGeld !== null ? (summeWert ? w.wert / summeWert * gesamtProzent : 0) : (minuten ? w.min / minuten * gesamtProzent : 0));
const hundert = rohP.map(p => Math.floor(p * 100 + 1e-9));
let restP = Math.round(gesamtProzent * 100) - hundert.reduce((a, b) => a + b, 0);
rohP.map((p, i) => ({ i, f: p * 100 - hundert[i] })).sort((a, b) => b.f - a.f).forEach(x => { if (restP > 0) { hundert[x.i]++; restP--; } });
wochenListe.forEach((w, i) => { w.prozent = hundert[i] / 100; });
const prozent = w => w.prozent;
const wochenTabelle = '<table class="wochen"><thead><tr><th>Woche</th><th>Zeitraum</th><th class="r">Zeit</th><th class="r">' + (mitBudget ? 'vom Budget' : 'Anteil Zeit') + '</th></tr></thead><tbody>' +
  wochenListe.map(w => '<tr><td>KW ' + w.kw + '</td><td>' + esc(spanne(w.a, w.b)) + '</td><td class="r">' + hhmm(w.min) + '</td><td class="r">' + zahl2(prozent(w)) + ' %</td></tr>').join('') +
  '</tbody><tfoot><tr><td colspan="2">Gesamt' + (mitBudget ? ' (Budget ' + budgetText + ')' : '') + '</td><td class="r">' + hhmm(minuten) + '</td><td class="r">' + zahl2(gesamtProzent) + ' %</td></tr></tfoot></table>';

const nachweis = '<table class="nachweis"><colgroup><col style="width:21mm"><col style="width:40mm"><col><col style="width:16mm"></colgroup><thead><tr><th>Datum</th><th>Aufgabe</th><th>Notiz</th><th class="r">Zeit</th></tr></thead>' +
  wochenListe.map(w => '<tbody><tr class="kw"><td colspan="3">KW ' + w.kw + ' · ' + esc(spanne(w.a, w.b)) + '</td><td class="r">' + hhmm(w.min) + '</td></tr>' +
    w.zeilen.map(z => '<tr><td class="datum">' + TAGE[z.tag.weekday] + ' ' + z.tag.toFormat('dd.LL.') + '</td><td>' + esc(z.aufgabe) + '</td><td class="notiz">' + (z.notiz ? esc(z.notiz) : '<span class="leer">–</span>') + (z.unbillable ? '<div class="hinweis">nicht berechnet</div>' : '') + '</td><td class="r">' + hhmm(z.sek / 60) + '</td></tr>').join('') + '</tbody>').join('') +
  '</table>';

const hinweise = [];
if (ausserhalb.length) hinweise.push(ausserhalb.length + ' Eintrag/Einträge liegen außerhalb des Projektzeitraums und sind enthalten.');
if (nichtBerechnetSek) hinweise.push('Nicht berechnete Zeit: ' + hhmm(Math.round(nichtBerechnetSek / 60)) + ' h (nicht in der Summe).');

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><style>
${CD.fontCss}
@page { size: A4; margin: 12mm 0 16mm 0; }
@page :first { margin-top: 0; }
* { box-sizing: border-box; }
body { margin: 0; font-family: '${CD.schrift}', sans-serif; color: ${C.dunkel}; font-size: 9.5pt; line-height: 1.4; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
